// Maps the language you picked to an Edge TTS voice name.
// Add a language by adding ONE row. Any voice from `edge-tts --list-voices` works.
const VOICES = {
  'English (US)':        { name: 'English',              voice: 'en-US-GuyNeural' },
  'Vietnamese':          { name: 'Vietnamese',           voice: 'vi-VN-NamMinhNeural' },
  'Spanish':             { name: 'Spanish',              voice: 'es-ES-AlvaroNeural' },
  'French':              { name: 'French',               voice: 'fr-FR-HenriNeural' },
  'German':              { name: 'German',               voice: 'de-DE-ConradNeural' },
  'Portuguese (Brazil)': { name: 'Brazilian Portuguese', voice: 'pt-BR-AntonioNeural' },
  'Indonesian':          { name: 'Indonesian',           voice: 'id-ID-ArdiNeural' },
};

const picked = $json['Language'];
const cfg = VOICES[picked];
if (!cfg) {
  throw new Error(
    `No Edge TTS voice mapped for "${picked}". Add a row to the VOICES map in this node. ` +
    `Run "edge-tts --list-voices" to see every available voice.`
  );
}

const text = ($json['Text'] || '').trim();
if (!text) throw new Error('The Text field is empty - nothing to speak.');

return { ...$json, text, languageName: cfg.name, voice: cfg.voice };

// One folder per run so two runs can never overwrite each other.
// submittedAt is unique per form submission and safe to use as an id.
const runId = ($('Text and language input form').item.json.submittedAt || String(Date.now()))
  .replace(/[^a-zA-Z0-9]/g, '');
const dir = `/tmp/edge-tts-${runId}`;
return {
  ...$json,
  dir,
  textPath: `${dir}/input.txt`,
  audioPath: `${dir}/voiceover.mp3`,
  subtitlePath: `${dir}/voiceover.ass`,
};

// The Read/Write File node writes a binary, so turn the text into one first.
// Read the text from Prepare file paths, not from $json: an Execute Command node
// replaces the item with its own stdout/stderr/exitCode, so anything set before it
// is gone by the time you get here. Cross-reference the node that still has it.
const paths = $('Prepare file paths for this run').item.json;
return {
  json: paths,
  binary: {
    textFile: {
      data: Buffer.from(paths.text, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'input.txt',
    },
  },
};

// stdout: line 1 = total duration, then the silencedetect markers.
const lines = ($json.stdout || '').trim().split('\n');
const duration = parseFloat(lines[0]) || 0;
const paths = $('Prepare file paths for this run').item.json;
const text = paths.text || '';
const words = text.split(/\s+/).filter(Boolean);
if (!duration || !words.length) {
  throw new Error(
    'Could not read the audio duration, or the text was empty. ' +
    'Check that edge-tts and ffmpeg/ffprobe are installed and on the PATH of the process running n8n.'
  );
}

// ── Pair the silencedetect markers into intervals ────────────────────────────
const marks = [];
for (const l of lines.slice(1)) {
  const m = l.match(/silence_(start|end):\s*([0-9.]+)/);
  if (m) marks.push({ type: m[1], t: parseFloat(m[2]) });
}
const silences = [];
let open = null;
for (const m of marks) {
  if (m.type === 'start') open = { start: m.t };
  else if (open) { open.end = m.t; silences.push(open); open = null; }
}
if (open) { open.end = duration; silences.push(open); }

// ── Speech segments = everything that is not silence ─────────────────────────
// Edge TTS pads ~0.2s of lead-in, ~0.9s of tail, and pauses ~1s at every full stop.
// On a 12s clip that is over 20% silence. Spreading the whole file duration across
// the words stretches every caption by that much and the voice ends up ahead of the
// highlight. Lay the words out on speech time only.
const speech = [];
let cursor = 0;
for (const s of silences) {
  if (s.start > cursor) speech.push({ start: cursor, end: s.start });
  cursor = Math.max(cursor, s.end);
}
if (cursor < duration) speech.push({ start: cursor, end: duration });
if (!speech.length) speech.push({ start: 0, end: duration });

// ── Anchor each sentence to the speech it is actually spoken in ──────────────
// Character-proportional layout across ALL speech does not line up with where the
// sentences really start: measured on a real clip a sentence was drawn 1.06s before
// the voice reached it. Edge TTS pauses ~1s at a full stop but only ~0.2s at a comma
// (measured: 0.87-1.04s vs 0.16-0.25s), so half a second separates the two cleanly.
// Merge speech split by a comma back together and each group is one sentence.
const SENTENCE_GAP = 0.5;
const groups = [];
for (const seg of speech) {
  const last = groups[groups.length - 1];
  if (last && seg.start - last.end < SENTENCE_GAP) {
    last.end = seg.end;
    last.segs.push(seg);
  } else {
    groups.push({ start: seg.start, end: seg.end, segs: [seg] });
  }
}
const sentences = (text.match(/[^.!?…]+[.!?…]+["'”’)\]]*\s*/g) || [text])
  .map((s) => s.trim()).filter(Boolean);

function layout(wordList, segs) {
  const total = segs.reduce((a, s) => a + (s.end - s.start), 0) || 0.001;
  const chars = wordList.reduce((a, w) => a + w.length, 0) || 1;
  const toReal = (offset) => {
    let acc = 0;
    for (const s of segs) {
      const len = s.end - s.start;
      if (offset <= acc + len) return s.start + (offset - acc);
      acc += len;
    }
    return segs[segs.length - 1].end;
  };
  let o = 0;
  return wordList.map((w) => {
    const dur = (w.length / chars) * total;
    const start = toReal(o);
    o += dur;
    return { word: w, start, end: toReal(o) };
  });
}

// Exact when the sentence count matches the speech groups; falls back to the plain
// global layout rather than guessing when it does not (abbreviations, other voices).
let captions;
if (sentences.length === groups.length && sentences.length > 0) {
  captions = [];
  sentences.forEach((sent, i) => {
    captions.push(...layout(sent.split(/\s+/).filter(Boolean), groups[i].segs));
  });
} else {
  captions = layout(words, speech);
}

return { json: { ...paths, duration, captions } };

const item = $json;
const captions = item.captions || [];
function fmt(t) {
  const cs = Math.round(t * 100);
  const h = Math.floor(cs / 360000);
  const m = Math.floor((cs % 360000) / 6000);
  const s = Math.floor((cs % 6000) / 100);
  const c = cs % 100;
  return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(c).padStart(2, '0')}`;
}

// Group words into lines by CHARACTER budget, not word count. A fixed word count
// breaks on languages with long words: 6 short English words fit on screen, 6 German
// compounds ("Zufriedenheit auszudrucken") run off both edges. ~28 chars is what fits
// 1080px at Arial 64 with the 60px side margins set below.
const MAX_CHARS = 28;
const MAX_WORDS = 7;

// A line must never carry the start of the next sentence. Edge TTS pauses ~1s at a
// full stop, so "blue? It is not" on one line shows "It is not" a second before it is
// spoken. Breaking on the sentence costs a short tail line; that line is still correct.
const SENTENCE_END = /[.!?…]["'”’)\]]?$/;
const groups = [];
let cur = [];
let curLen = 0;
for (const w of captions) {
  const wLen = w.word.length + 1;
  if (cur.length && (curLen + wLen > MAX_CHARS || cur.length >= MAX_WORDS)) {
    groups.push(cur); cur = []; curLen = 0;
  }
  cur.push(w);
  curLen += wLen;
  if (SENTENCE_END.test(w.word)) { groups.push(cur); cur = []; curLen = 0; }
}
if (cur.length) groups.push(cur);

const lines = groups.map((chunk, i) => {
  const start = chunk[0].start;
  // Hold each line until the next begins. Word timings stop where the voice stops,
  // which would otherwise blank the screen for the ~1s pause at every full stop.
  // The karaoke still finishes on the voice; the line just stays fully highlighted.
  const next = groups[i + 1];
  const end = next ? next[0].start : chunk[chunk.length - 1].end;
  const text = chunk.map((w) => {
    const dur = Math.max(1, Math.round((w.end - w.start) * 100));
    return `{\\k${dur}}${w.word} `;
  }).join('');
  return `Dialogue: 0,${fmt(start)},${fmt(end)},Default,,0,0,0,,${text.trim()}`;
});

// WrapStyle 0 = smart wrapping. WrapStyle 2 means NO wrapping at all: an over-long
// line silently runs off both edges instead of breaking. This is the safety net for a
// single very long word that still busts MAX_CHARS.
const ass = `[Script Info]
ScriptType: v4.00+
PlayResX: 1080
PlayResY: 1920
WrapStyle: 0

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,Arial,64,&H00FFFFFF,&H0000FFFF,&H+1234567890,&H80000000,-1,0,0,0,100,100,0,0,1,3,2,2,60,60,150,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
${lines.join('\n')}
`;

return {
  json: { ...item, lineCount: lines.length },
  binary: {
    subtitle: {
      data: Buffer.from(ass).toString('base64'),
      mimeType: 'text/plain',
      fileName: 'voiceover.ass',
    },
  },
};
